const scenes=[];function updateMotion(){document.documentElement.classList.toggle('motion-paused',paused);$('#motion-toggle').setAttribute('aria-pressed',String(paused));$('#motion-toggle').innerHTML=paused?'Enable motion <span>▷</span>':'Pause motion <span>Ⅱ</span>';scenes.forEach(s=>s.setPaused(paused));}
