$('#application-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const data=Object.fromEntries(new FormData(form));const error=validateEnquiry(data);if(error){$('#form-status').textContent=error;return;}
 const status=$('#form-status'),button=$('.submit-button');$('#download-enquiry').hidden=true;
 if(!settings.enquiryEndpoint){if(downloadUrl)URL.revokeObjectURL(downloadUrl);const lines=['HENOK ASRAT — TRAINING ENQUIRY','Prepared locally; not submitted. No place reserved.','',`Name: ${data.name}`,`Email: ${data.email}`,`WhatsApp: ${data.phone}`,`Format: ${data.format}`,`Level: ${data.level}`,`Interest: ${data.message || 'Not specified'}`,'','Consent: agreed to be contacted about this enquiry.'];downloadUrl=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=$('#download-enquiry');a.href=downloadUrl;a.download='henok-training-enquiry.txt';a.hidden=false;status.textContent='Your enquiry is ready to download. It has not been sent; registrations are not open in this preview.';return;}
 button.disabled=true;status.textContent='Sending your enquiry…';try{const response=await fetch(settings.enquiryEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('server');const result=await response.json();if(result.accepted!==true)throw new Error('unconfirmed');status.textContent='Your enquiry has been received. Your place is awaiting confirmation.';form.reset();syncLevels();}catch{status.textContent='We could not confirm delivery. Your details remain in the form. Please try again.';}finally{button.disabled=false;}});
$('#newsletter').addEventListener('submit',async e=>{e.preventDefault();const status=$('#newsletter-status');if(!settings.newsletterEndpoint){status.textContent='Newsletter registration is not open yet. Your email has not been stored or sent.';return;}const button=e.currentTarget.querySelector('button');button.disabled=true;try{const r=await fetch(settings.newsletterEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#newsletter-email').value}),signal:AbortSignal.timeout(15000)});if(!r.ok)throw new Error();const data=await r.json();if(data.accepted!==true)throw new Error();status.textContent='Please check your email to confirm your subscription.';}catch{status.textContent='Unable to confirm your subscription. Please try again.';}finally{button.disabled=false;}});
